def seed_v5(db, t):
    for i, p in enumerate(PAGES):
        at = t - (len(PAGES) - i) * H
        pg = M.Page(**p, published=True, version=1, updated_at=at, created_at=at, updated_by="@vibeloop.staff")
        db.add(pg); db.flush()
        db.add(M.PageVersion(slug=pg.slug, version=1, by="@vibeloop.staff", note="seeded", at=at, snapshot={
            "module": pg.module, "kind": pg.kind, "title": pg.title, "summary": pg.summary, "body": pg.body, "coverUrl": None,
            "itemsKind": pg.items_kind, "items": pg.items, "published": True, "order": pg.order}))
    # Real Talk: a fan with a PAID demo order for u1's preset pack
    db.add(M.Order(id="ord_demo_m3_presets", user_id="m3", kind="product", ref_id="prod_u1_presets", creator_id="u1", amount=14900, currency="INR",
                   provider="razorpay", provider_ref="demo_paid", test_mode=True, status="paid", fee=1192, note="demo order (seed)", at=t - 2 * D, paid_at=t - 2 * D))
    db.add(M.Review(id="rv_demo_presets", type="product", author_id="m3", target_id="prod_u1_presets", rating=5, verified_purchase=True,
                    text="Warm tones without the orange-face look. The night-market preset alone was worth it.", at=t - D, updated_at=t - D))
    db.add_all([M.Review(id="rv_vouch_riya_u1", type="vouch", author_id="usr_riya", target_id="u1", rating=5, context="collab",
                         text="Shot a food ep together — Aanya was on time, prepped, and funny on camera. Would collab again.", at=t - 3 * D, updated_at=t - 3 * D),
                M.Review(id="rv_vouch_u3_u1", type="vouch", author_id="u3", target_id="u1", rating=4, context="creator",
                         text="Super responsive and honest about what works. Her breakfast series is a masterclass in hooks.", at=t - 2 * D, updated_at=t - 2 * D)])
    db.add_all([M.Ticket(id="su_demo_urgent", code="SU-7KQ2M", reporter_id="m4", category="harassment", target_type="user", target_id="x1", priority="urgent",
                         details="This account keeps messaging me after I said stop, and now says it knows where I study. I feel unsafe.", status="open", at=t - 40 * 60_000, updated_at=t - 40 * 60_000,
                         history=[{"at": t - 40 * 60_000, "by": "@zoya.fan", "status": "open", "public": "We got it. Your ticket is in the queue."}]),
                M.Ticket(id="su_demo_scam", code="SU-3HD8P", reporter_id="u3", category="scam", target_type="post", target_id="p5", priority="high",
                         details="Comments under this Drop push a 'double your money' link. Looks like a scam.", status="reviewing", at=t - 5 * H, updated_at=t - 3 * H,
                         history=[{"at": t - 5 * H, "by": "@meera.learns", "status": "open", "public": "We got it. Your ticket is in the queue."},
                                  {"at": t - 3 * H, "by": "@vibeloop.staff", "status": "reviewing", "note": "Checking the linked domain", "public": "A real human is looking at your report now."}])])
